exercises.tests:
def test_first_word():
    assert first_word == "automation", f"ожидалось 'automation', получено {first_word!r}"


def test_last_char():
    assert last_char == "g", f"ожидался последний символ 'g', получено {last_char!r}"


def test_reversed_text():
    assert reversed_text == "gnitset noitamotua", f"получено {reversed_text!r}"

def test_email_and_password_split():
    assert email == "user@example.com", f"ожидался email 'user@example.com', получено {email}"
    assert password == "Qwerty123", f"ожидался password 'Qwerty123', получено {password}"


def test_is_valid_email():
    assert is_valid_email is True, "email 'user@example.com' валиден, ожидается True"


def test_login_message():
    assert login_message == "Login: user@example.com, password length: 9", f"получено: {login_message}"

def test_clean_log_stripped():
    assert clean_log == "[ERROR] status=500 duration=1234ms", f"строка должна быть без пробелов по краям, получено {clean_log!r}"


def test_has_error():
    assert has_error is True, "в строке есть подстрока 'ERROR', has_error должен быть True"


def test_duration_ms():
    assert duration_ms == 1234, f"ожидалось duration_ms=1234, получено {duration_ms}"


def test_message_format():
    assert message == "Duration: 1.23 sec", f"получено {message!r}"

def test_raw_equal_is_false():
    assert raw_equal is False, "raw_value содержит лишний '\\n' на конце, поэтому прямое сравнение с expected должно быть False"


def test_stripped_equal_is_true():
    assert stripped_equal is True, "после .strip() лишний перенос строки убирается, сравнение должно быть True"
